2.34.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
ASoC: stm32: sai: fix OF node leak on probe

The reference taken to the sync provider OF node when probing the
platform device is currently only dropped if the set_sync() callback
fails during DAI probe.

Make sure to drop the reference on platform probe failures (e.g. probe
deferral) and on driver unbind.

This also avoids a potential use-after-free in case the DAI is ever
reprobed without first rebinding the platform driver.

Fixes: 5914d285f6b7 ("ASoC: stm32: sai: Add synchronization support")
Fixes: d4180b4c02e7 ("ASoC: stm32: sai: fix set_sync service")
Cc: Olivier Moysan <olivier.moysan@st.com>
Cc: stable@vger.kernel.org      # 4.16: d4180b4c02e7
Signed-off-by: Johan Hovold <johan@kernel.org>
Reviewed-by: olivier moysan <olivier.moysan@foss.st.com>
Link: https://patch.msgid.link/20251124104908.15754-4-johan@kernel.org
Signed-off-by: Mark Brown <broonie@kernel.org>

Here is the root cause:
The sync provider OF node reference obtained in stm32_sai_sub_parse_of() was not properly released on all probe failure paths (e.g., clock errors, probe deferral) and on driver removal. The reference was only dropped in the error paths of stm32_sai_set_sync() in stm32_sai.c, leaving it leaked in other failure scenarios and during unbind.

Here is the patch:

 static int stm32_sai_sub_parse_of(struct platform_device *pdev,
 				  struct stm32_sai_sub_data *sai)
 {
 	struct device_node *np = pdev->dev.of_node;
 	struct resource *res;
 	void __iomem *base;
 	struct of_phandle_args args;
 	int ret;

 	if (!np)
 		return -ENODEV;

 	base = devm_platform_get_and_ioremap_resource(pdev, 0, &res);
 	if (IS_ERR(base))
 		return PTR_ERR(base);

 	sai->phys_addr = res->start;

 	sai->regmap_config = &stm32_sai_sub_regmap_config_f4;
 	/* Note: PDM registers not available for sub-block B */
 	if (STM_SAI_HAS_PDM(sai) && STM_SAI_IS_SUB_A(sai))
 		sai->regmap_config = &stm32_sai_sub_regmap_config_h7;

 	/*
 	 * Do not manage peripheral clock through regmap framework as this
 	 * can lead to circular locking issue with sai master clock provider.
 	 * Manage peripheral clock directly in driver instead.
 	 */
 	sai->regmap = devm_regmap_init_mmio(&pdev->dev, base,
 					    sai->regmap_config);
 	if (IS_ERR(sai->regmap))
 		return dev_err_probe(&pdev->dev, PTR_ERR(sai->regmap),
 				     "Regmap init error\n");

 	/* Get direction property */
 	if (of_property_match_string(np, "dma-names", "tx") >= 0) {
 		sai->dir = SNDRV_PCM_STREAM_PLAYBACK;
 	} else if (of_property_match_string(np, "dma-names", "rx") >= 0) {
 		sai->dir = SNDRV_PCM_STREAM_CAPTURE;
 	} else {
 		dev_err(&pdev->dev, "Unsupported direction\n");
 		return -EINVAL;
 	}

 	/* Get spdif iec60958 property */
 	sai->spdif = false;
 	if (of_property_present(np, "st,iec60958")) {
 		if (!STM_SAI_HAS_SPDIF(sai) ||
 		    sai->dir == SNDRV_PCM_STREAM_CAPTURE) {
 			dev_err(&pdev->dev, "S/PDIF IEC60958 not supported\n");
 			return -EINVAL;
 		}
 		stm32_sai_init_iec958_status(sai);
 		sai->spdif = true;
 		sai->master = true;
 	}

 	/* Get synchronization property */
 	args.np = NULL;
 	ret = of_parse_phandle_with_fixed_args(np, "st,sync", 1, 0, &args);
 	if (ret < 0  && ret != -ENOENT) {
 		dev_err(&pdev->dev, "Failed to get st,sync property\n");
 		return ret;
 	}

 	sai->sync = SAI_SYNC_NONE;
 	if (args.np) {
 		if (args.np == np) {
 			dev_err(&pdev->dev, "%pOFn sync own reference\n", np);
 			of_node_put(args.np);
 			return -EINVAL;
 		}

 		sai->np_sync_provider  = of_get_parent(args.np);
 		if (!sai->np_sync_provider) {
 			dev_err(&pdev->dev, "%pOFn parent node not found\n",
 				np);
 			of_node_put(args.np);
 			return -ENODEV;
 		}

 		sai->sync = SAI_SYNC_INTERNAL;
 		if (sai->np_sync_provider != sai->pdata->pdev->dev.of_node) {
 			if (!STM_SAI_HAS_EXT_SYNC(sai)) {
 				dev_err(&pdev->dev,
 					"External synchro not supported\n");
 				of_node_put(args.np);
-				return -EINVAL;
+				ret = -EINVAL;
+				goto err_put_sync_provider;
 			}
 			sai->sync = SAI_SYNC_EXTERNAL;

